def main():
    conn = sqlite3.connect(DB)
    c = conn.cursor()
    updated = 0
    for slug, bio_html in PERSONS.items():
        c.execute('SELECT id FROM persons WHERE slug=?', (slug,))
        row = c.fetchone()
        if row:
            c.execute(
                'UPDATE persons SET bio_html=?, review_status=?, confidence=? WHERE slug=?',
                (bio_html, 'DRAFT', 'MEDIUM', slug)
            )
            word_count = len(bio_html.split())
            print(f'  Updated {slug}: {len(bio_html)} chars / ~{word_count} words')
            updated += 1
        else:
            print(f'  WARNING: person not found: {slug}')
    conn.commit()
    conn.close()
    print(f'\nDone: {updated} persons updated.')


if __name__ == '__main__':
    main()
